contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint lockTime, uint am, uint minSum) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (am)); require(am <= 1000000000000000000000000000000);
        require(address(this).balance >= am);

        c.SetMinSum(minSum); if (__ESBMC_reverted()) return;
        c.Initialized(); if (__ESBMC_reverted()) return;
        c.SetLogFile(address(this)); if (__ESBMC_reverted()) return;

        c.Put{value: am}(lockTime); if (__ESBMC_reverted()) return;
        (uint unlockTimeBefore, uint balanceBefore) = c.Acc(address(this)); if (__ESBMC_reverted()) return;
        uint cBalanceBefore = address(c).balance;

        bool reverted;
        c.Collect(am); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        (uint unlockTimeAfter, uint balanceAfter) = c.Acc(address(this)); if (__ESBMC_reverted()) return;
        uint cBalanceAfter = address(c).balance;

        bool preconditionsMet = unlockTimeBefore != 0 && balanceBefore >= minSum && balanceBefore >= am && block.timestamp > unlockTimeBefore;
        assert((reverted && !preconditionsMet) || (!reverted && preconditionsMet && balanceAfter == balanceBefore - am && cBalanceAfter == cBalanceBefore - am));
    }

    receive() external payable {}
}

