pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PENNY_BY_PENNY c;

    function setUp() public {
        c = new PENNY_BY_PENNY();
    }

    function _run(uint256 lockTime, uint256 am, uint256 minSum) internal {
        am = bound(am, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= am);
        try c.SetMinSum(minSum) {} catch { return; }
        try c.Initialized() {} catch { return; }
        try c.SetLogFile(address(this)) {} catch { return; }
        try c.Put{value: am}(lockTime) {} catch { return; }
        uint256 unlockTimeBefore;
        uint256 balanceBefore;
        try c.Acc(address(this)) returns (uint256 __r0, uint256 __r1) { unlockTimeBefore = __r0; balanceBefore = __r1; } catch { return; }
        uint cBalanceBefore = address(c).balance;
        bool reverted;
        try c.Collect(am) { reverted = false; } catch { reverted = true; }
        uint256 unlockTimeAfter;
        uint256 balanceAfter;
        try c.Acc(address(this)) returns (uint256 __r0, uint256 __r1) { unlockTimeAfter = __r0; balanceAfter = __r1; } catch { return; }
        uint cBalanceAfter = address(c).balance;
        bool preconditionsMet = unlockTimeBefore != 0 && balanceBefore >= minSum && balanceBefore >= am && block.timestamp > unlockTimeBefore;
        assertTrue((reverted && !preconditionsMet) || (!reverted && preconditionsMet && balanceAfter == balanceBefore - am && cBalanceAfter == cBalanceBefore - am));
    }

    function testFuzz_run(uint256 lockTime, uint256 am, uint256 minSum) public {
        _run(lockTime, am, minSum);
    }

    receive() external payable {}
}
